begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('93000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'openingBalancesSupported',true)$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.seed_opening(n integer,days integer,due date,raw_terms text default null,receipt uuid default null) returns void language plpgsql as $$begin
 values(pg_temp.i(n),pg_temp.i(1),pg_temp.i(101),pg_temp.i(601),'TEST supplier','TEST-OPEN-'||n,'2025-03-01',days,due,100000,'TEST source unpaid balance; prior payments unknown',receipt,pg_temp.i(11),'opening','2026-11-05',jsonb_build_object('file','TEST-payables.pdf','sha256',repeat('a',64),'page',1,'row',n,'termsText',raw_terms,'locationScope','All locations'));
end$$;
create function pg_temp.sstate(n integer default 1001) returns jsonb language sql as $$select public.agri_command('supplier_invoice_history',pg_temp.ctx()||jsonb_build_object('billId',pg_temp.i(n)))->'invoice'$$;
create function pg_temp.spay(n integer,value bigint default 20000) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'billId',pg_temp.i(1001),'expectedVersion',pg_temp.sstate()->'version','expectedBalance',pg_temp.sstate()->'balance','amount',value,'method','bank','paidOn',(now() at time zone 'Asia/Manila')::date,'reference','TEST-PAY-'||n,'reason','TEST verified payment after opening','confirmed',true)$$;
select pg_temp.login(11);
select pg_temp.login(11);
set local role authenticated;
select pg_temp.login(12);
reset role;
select pg_temp.login(11);
select line from tap_results;select * from finish();rollback;
